47	/**
48	 * Mail-platform DNS constants. Customers with a domain registered ELSEWHERE
49	 * publish these at their registrar so mail flows through the Nxeon mail server;
50	 * customers whose domain is inside Nxeon have this managed for them.
51	 */
52	const MAIL_HOST = "mail.nxeon.cloud";
53	const MAIL_MX_PRIORITY = 10;
54	// The mechanism that authorises our sending host; kept separate from the full
55	// record so the deliverability check can look for it inside whatever SPF the
56	// customer already publishes rather than demanding a byte-exact match.
57	const SPF_INCLUDE = "nxeon.cloud";
58	const SPF_VALUE = `v=spf1 include:${SPF_INCLUDE} ~all`;
59	const DMARC_VALUE = "v=DMARC1; p=none; rua=mailto:dmarc@nxeon.cloud";
60	const DKIM_SELECTOR = "dkim";
61	
62	// A syntactically valid registrable domain (labels, no scheme, no trailing dot).
63	const domainRe =
64	  /^(?=.{1,253}$)(?:[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?\.)+[a-z]{2,63}$/;
65	
66	export type DnsRecord = {
67	  type: "TXT" | "MX";
68	  label: string; // human label for the row
69	  host: string; // record host / name
70	  value: string;
71	  priority?: number;
72	  note?: string;
73	};
74	
75	/**
76	 * Business Email — mailbox hosting per registered domain.
77	 *
78	 * An `EmailPlan` is a pricing tier (N mailboxes, GB/mailbox, price, term). A
79	 * customer subscribes one of their own domains to a tier (`EmailSubscription`),
80	 * which debits the wallet, then manages individual `Mailbox` rows under it.
81	 *
82	 * Mail delivery runs through a self-hosted Mailcow server, reached via lib/mailcow.ts
83	 * (config from MAILCOW_API_URL / MAILCOW_API_KEY). Creating a Mailbox row records
84	 * intent (status PROVISIONING); we then attempt to provision the real mailbox on
85	 * Mailcow and flip the row to ACTIVE, or FAILED if the call errors. All Mailcow
86	 * calls are additive and failure-tolerant — a Mailcow outage never breaks the
87	 * order flow; the row persists and can be retried via retryMailboxProvision.
88	 *
89	 * This module owns:
90	 *   - orderEmailHosting (customer subscribe)
91	 *   - addMailbox / removeMailbox / retryMailboxProvision (customer mailbox management)
92	 *   - adminSaveEmailPlan / adminToggleEmailPlan / adminDeleteEmailPlan (CRUD)
93	 */
94	
95	type Result = { error?: string; ok?: boolean; warning?: string };
96	
97	/**
98	 * Provision (or re-provision) a mailbox on Mailcow. Never throws — records the
99	 * outcome on the Mailbox row (status ACTIVE on success, FAILED on error) and
100	 * returns it. When Mailcow isn't configured the row is left PROVISIONING so it
101	 * can be picked up once the integration is wired.
102	 */
103	async function provisionMailboxOnMailcow(mailbox: {
104	  id: string;
105	  address: string;
106	  quotaMB: number | null;
107	  subscription: { domainName: string };
108	}): Promise<"ACTIVE" | "FAILED" | "PROVISIONING"> {
109	  if (!mailcowConfigured()) return "PROVISIONING";
110	
111	  const [localPart] = mailbox.address.split("@");
112	  const domain = mailbox.subscription.domainName;
113	  const quotaMB = mailbox.quotaMB ?? 1024;
114	
115	  try {
116	    // Ensure the mail domain exists before adding the mailbox.
117	    if (!(await mcDomainExists(domain))) {
118	      // A concurrent create or pre-existing domain can still error here; ignore
119	      // and let the mailbox add be the real signal.
120	      await mcCreateDomain(domain).catch(() => {});
121	    }
122	
123	    const password = randomBytes(18).toString("base64url");
124	    await mcCreateMailbox({
125	      localPart,
126	      domain,
127	      name: mailbox.address,
128	      password,
129	      quotaMB,
130	    });
131	
132	    await db.mailbox.update({
133	      where: { id: mailbox.id },
134	      data: { status: "ACTIVE", passwordEnc: encryptSecret(password) },
135	    });
136	    return "ACTIVE";
137	  } catch (e) {
138	    await db.mailbox
139	      .update({ where: { id: mailbox.id }, data: { status: "FAILED" } })
140	      .catch(() => {});
141	    console.warn(`[mailcow] provisioning ${mailbox.address} failed:`, e);
142	    return "FAILED";
143	  }
144	}
145	
146	// ---------- Admin CRUD (billing area) ----------
147	
148	const planSchema = z.object({
149	  id: z.string().optional(),
150	  name: z.string().min(2).max(80),
151	  mailboxes: z.coerce.number().int().min(1).max(100000),
152	  storageGB: z.coerce.number().int().min(1).max(100000),
153	  priceCents: z.coerce.number().int().min(0).max(100000000),
154	  termMonths: z.coerce.number().int().min(1).max(36),
155	  sortOrder: z.coerce.number().int().min(0).max(100000),
156	});
157	
158	/** Create or update an EmailPlan tier. ADMIN/BILLING only, audit-logged. */
159	export async function adminSaveEmailPlan(
160	  prev: Result | undefined,
161	  formData: FormData,
162	): Promise<Result> {
163	  const admin = await requireArea("billing");
164	
165	  const parsed = planSchema.safeParse({
166	    id: formData.get("id") || undefined,
167	    name: formData.get("name"),
168	    mailboxes: formData.get("mailboxes"),
169	    storageGB: formData.get("storageGB"),
170	    priceCents: formData.get("priceCents"),
171	    termMonths: formData.get("termMonths"),
172	    sortOrder: formData.get("sortOrder") ?? 0,
173	  });
174	  if (!parsed.success) {
175	    return { error: parsed.error.issues[0]?.message ?? "Check the tier values." };
176	  }
177	  const d = parsed.data;
178	  const active = formData.get("active") === "on";
179	
180	  const data = {
181	    name: d.name.trim(),
182	    mailboxes: d.mailboxes,
183	    storageGB: d.storageGB,
184	    priceCents: d.priceCents,
185	    termMonths: d.termMonths,
186	    active,
187	    sortOrder: d.sortOrder,
188	  };
189	
190	  if (d.id) {
191	    const existing = await db.emailPlan.findUnique({ where: { id: d.id } });
192	    if (!existing) return { error: "Tier not found." };
193	    await db.emailPlan.update({ where: { id: d.id }, data });
194	  } else {
195	    await db.emailPlan.create({ data });
196	  }
197	
198	  await db.auditLog.create({
199	    data: {
200	      userId: admin.id,
201	      action: d.id ? "emailplan.update" : "emailplan.create",
202	      detail: `${data.name} — ${data.mailboxes} mbx / ${data.storageGB}GB (${(data.priceCents / 100).toFixed(2)}/${data.termMonths}mo)`,
203	    },
204	  });
205	  revalidatePath("/admin/email-plans");
206	  return { ok: true };
207	}
