209	/** Flip a tier's active flag. */
210	export async function adminToggleEmailPlan(id: string): Promise<void> {
211	  const admin = await requireArea("billing");
212	  const plan = await db.emailPlan.findUnique({ where: { id } });
213	  if (!plan) return;
214	  await db.emailPlan.update({ where: { id }, data: { active: !plan.active } });
215	  await db.auditLog.create({
216	    data: { userId: admin.id, action: "emailplan.toggle", detail: `${plan.name} → active=${!plan.active}` },
217	  });
218	  revalidatePath("/admin/email-plans");
219	}
220	
221	/** Delete a tier. Refused while subscriptions reference it. */
222	export async function adminDeleteEmailPlan(id: string): Promise<Result> {
223	  const admin = await requireArea("billing");
224	  const plan = await db.emailPlan.findUnique({
225	    where: { id },
226	    include: { _count: { select: { subscriptions: true } } },
227	  });
228	  if (!plan) return { error: "Tier not found." };
229	  if (plan._count.subscriptions > 0) {
230	    return {
231	      error: `Can't delete — ${plan._count.subscriptions} subscription(s) use this tier. Disable it instead.`,
232	    };
233	  }
234	  await db.emailPlan.delete({ where: { id } });
235	  await db.auditLog.create({
236	    data: { userId: admin.id, action: "emailplan.delete", detail: plan.name },
237	  });
238	  revalidatePath("/admin/email-plans");
239	  return { ok: true };
240	}
241	
242	// ---------- Customer ordering ----------
243	
244	/**
245	 * Subscribe one of the caller's registered domains to an email plan. Validates
246	 * domain ownership + plan availability, then atomically debits the wallet and
247	 * creates the EmailSubscription with an expiry set from the plan term.
248	 *
249	 * The subscription is created ACTIVE (billing-wise), but no mailboxes are
250	 * provisioned with a mail provider yet — that integration is pending, and the
251	 * UI surfaces every mailbox as "provisioning" until it lands.
252	 */
253	export async function orderEmailHosting(
254	  domainName: string,
255	  emailPlanId: string,
256	  termMonthsRaw?: number,
257	  /**
258	   * "Apply my balance" — mirrors the VPS/hosting wizard toggle. Defaults ON (only an
259	   * explicit `false` turns it off) so existing callers keep applying the wallet first.
260	   * When the balance doesn't fully cover the term charge — the toggle is off, or the
261	   * balance is short — the remainder is charged to a card that funds the wallet, then
262	   * the wallet path (`orderEmailHostingCore`) places the subscription.
263	   */
264	  useWallet: boolean = true,
265	): Promise<Result | { checkout: EmbeddedCheckout }> {
266	  const user = await requireUser();
267	  // Spend path: block while an admin is impersonating, so support cannot buy a
268	  // subscription with a customer's wallet while acting as them.
269	  await assertNotImpersonating();
270	  // Purchase gate: an unverified address means we cannot reach the person we
271	  // are about to charge. See lib/email-verification.ts.
272	  const unverified = await emailVerificationError(user);
273	  if (unverified) return { error: unverified };
274	
275	  const name = String(domainName ?? "")
276	    .trim()
277	    .toLowerCase()
278	    .replace(/\.$/, "");
279	  if (!name) return { error: "Enter a domain." };
280	  if (!domainRe.test(name)) return { error: "Enter a valid domain (e.g. example.com)." };
281	
282	  // Price the term for the wallet/card split. Business Email has no first-month-free,
283	  // so the amount due today IS the full term charge. Shared `emailChargeCents` with the
284	  // core below so the split and the debit can never use different formulas.
285	  const planForSplit = await db.emailPlan.findUnique({ where: { id: emailPlanId } });
286	  if (!planForSplit || !planForSplit.active) return { error: "That email plan isn't available." };
287	  const term = normalizeProductTerm(termMonthsRaw);
288	  const { fullCharge } = await emailChargeCents(planForSplit, term);
289	  const { cardCents } = walletSplit({ dueCents: fullCharge, balanceCents: user.balanceCents, useWallet });
290	
291	  if (cardCents > 0) {
292	    // A card leg is due (the toggle is off, or the balance is short). Reject an already-
293	    // taken domain BEFORE opening a paid checkout (the core re-checks authoritatively at
294	    // fulfilment), then fund the remainder by card. On payment `fulfilCheckoutSession`
295	    // credits the card amount to the wallet and calls `orderEmailHostingCore`, which
296	    // debits the real charge — one debit path.
297	    const dupe = await db.emailSubscription.findFirst({ where: { domainName: name, status: { not: "CANCELLED" } } });
298	    if (dupe) {
299	      return {
300	        error:
301	          dupe.userId === user.id
302	            ? "This domain already has an email subscription."
303	            : "That domain is already set up for email on Nxeon. If it belongs to you, contact support and we'll verify ownership and move it across.",
304	      };
305	    }
306	    const checkout = await createEmailOrderCheckout(user, cardCents, { domainName: name, emailPlanId, termMonths: term });
307	    if (!checkout) return { error: "Card payments aren't set up yet — top up your wallet first." };
308	    return { checkout };
309	  }
310	
311	  // cardCents <= 0 → the wallet covers the term charge. EXISTING wallet path, unchanged.
312	  return orderEmailHostingCore(user, name, emailPlanId, termMonthsRaw);
313	}
314	
315	/** Term price for an email plan, in ONE place shared by the split pre-check and the
316	 *  authoritative debit (`orderEmailHostingCore`). `emailMonthlyBaseCents` is the plan's
317	 *  monthly base (seeded plans are monthly, so it is just `priceCents`). */
318	async function emailChargeCents(
319	  plan: Parameters<typeof emailMonthlyBaseCents>[0],
320	  term: number,
321	): Promise<{ annualPct: number; fullCharge: number }> {
322	  const annualPct = await annualDiscountPct();
323	  const fullCharge = termPriceCents(emailMonthlyBaseCents(plan), term, annualPct);
324	  return { annualPct, fullCharge };
325	}
326	
327	/**
328	 * The wallet-charging placement core, WITHOUT the auth/split preamble — takes the
329	 * already-loaded `user` explicitly so it runs from BOTH the interactive action
330	 * (`orderEmailHosting`, wallet path) and the card-funded fulfilment path
331	 * (`placeEmailCardOrder` → `fulfilCheckoutSession`). Everything below — the domain
332	 * dupe guard, pricing, the wallet debit and the subscription create — is byte-for-byte
333	 * the wallet-only logic that used to live inline in `orderEmailHosting`.
334	 */
335	async function orderEmailHostingCore(
336	  user: User,
337	  domainName: string,
338	  emailPlanId: string,
339	  termMonthsRaw?: number,
340	): Promise<Result> {
341	  const name = String(domainName ?? "")
342	    .trim()
343	    .toLowerCase()
344	    .replace(/\.$/, "");
345	  if (!name) return { error: "Enter a domain." };
346	  if (!domainRe.test(name)) return { error: "Enter a valid domain (e.g. example.com)." };
347	
348	  // Is the domain registered inside Nxeon? If so we control its DNS and can
349	  // treat mail as pre-verifiable; otherwise it's an EXTERNAL domain that must be
350	  // verified via DNS before mail flows.
351	  const inAccount = await db.domain.findFirst({ where: { name, userId: user.id } });
352	  const external = !inAccount;
353	
354	  const plan = await db.emailPlan.findUnique({ where: { id: emailPlanId } });
355	  if (!plan || !plan.active) return { error: "That email plan isn't available." };
356	
357	  // One subscription per domain — ACROSS ALL ACCOUNTS, not just this one.
358	  //
359	  // SECURITY (fixed 2026-07-25): this lookup was scoped to `userId: user.id`,
360	  // which let anyone buy a subscription for a domain another customer already
361	  // held. That was a cross-tenant email takeover: `addMailbox` only checks that
362	  // the SUBSCRIPTION belongs to the caller, and Mailcow keys mailboxes by
363	  // ADDRESS — so an attacker could create admin@victim.com under their own
364	  // subscription, call resetMailboxPassword() (which passes its ownership check
365	  // because the row is theirs), and have the password of the victim's real, live
366	  // mailbox handed back to them. Cost of the attack: the cheapest email plan.
367	  const dupe = await db.emailSubscription.findFirst({
368	    where: { domainName: name, status: { not: "CANCELLED" } },
369	  });
370	  if (dupe) {
371	    return {
372	      error:
373	        dupe.userId === user.id
374	          ? "This domain already has an email subscription."
375	          : "That domain is already set up for email on Nxeon. If it belongs to you, contact support and we'll verify ownership and move it across.",
376	    };
377	  }
378	
379	  // Seasonal promo = HONEST intro discount on the FIRST term only. The renewal
380	  // path (worker/product-renewals.ts) bills plan.priceCents unchanged, so the
381	  // strikethrough shown on the pricing page is the real renewal price and this
382	  // discounted value is the real first-term price — displayed === charged.
383	  // Managed first-month-free. `promoCharge` mirrors the pre-existing behaviour
384	  // (the first term is free); `fullCharge` is the plan price. The credit is granted
385	  // ONLY if the atomic claim inside the charge tx succeeds — otherwise (already
386	  // redeemed by this account/IP, or the promo is off) the subscription is created
387	  // at FULL price. The eligibility pre-check only picks the balance gate so a
388	  // first-time, $0-balance customer can still subscribe free.
389	  // First-month-free is scoped to Shared Web Hosting only — Business Email always
390	  // bills full. firstMonthFreeAppliesTo("EMAIL") is false, so promoEnabled is false.
391	  const promoEnabled = firstMonthFreeAppliesTo("EMAIL") && (await firstMonthFreeEnabled());
392	  const campaign = promoCampaignFromCookie(await cookies());
393	  const ipHash = hashIp(clientIp(await headers()), process.env.AUTH_SECRET ?? "nxeon") || null;
394	  // Billing term (Monthly / Annual). The annual rate is resolved ONCE, frozen onto
395	  // the subscription, charged up front and read back at renewal — displayed ===
396	  // charged === renewed. `emailMonthlyBaseCents` is the plan's monthly base (every
397	  // seeded plan is monthly, so it is just `priceCents`).
398	  const term = normalizeProductTerm(termMonthsRaw);
399	  const { annualPct, fullCharge } = await emailChargeCents(plan, term);
400	  // Business Email is NOT a first-month-free product (firstMonthFreeAppliesTo("EMAIL")
401	  // is false), so this stays the full term charge — kept for parity with the other flows.
402	  const promoCharge = 0;
403	  const eligible = promoEnabled && (await firstMonthFreeEligible(user.id, ipHash));
404	  const anticipated = eligible ? promoCharge : fullCharge;
405	  if (user.balanceCents < anticipated) {
406	    return { error: "Insufficient balance. Top up your wallet first." };
407	  }
408	
409	  try {
410	    await db.$transaction(async (tx) => {
411	      // Atomic claim inside the charge tx (mirrors lib/order.ts claimOrderCoupon).
412	      let debitCents = fullCharge;
413	      let promoClaimId: string | null = null;
414	      if (promoEnabled) {
415	        const claim = await claimFirstMonthFree(tx, {
416	          userId: user.id,
417	          ipHash,
418	          serviceType: "EMAIL",
419	          campaign,
420	          chargedCents: promoCharge,
421	        });
422	        if (claim.claimed) {
423	          debitCents = promoCharge;
424	          promoClaimId = claim.id;
425	        }
426	      }
427	      const note = debitCents < fullCharge ? " — First month free" : "";
428	      const effMonthly = term > 1 ? Math.round(fullCharge / term) : 0;
429	      const termLabel = term > 1 ? `${vpsTerm(term).label} ($${(effMonthly / 100).toFixed(2)}/mo)` : vpsTerm(term).label;
430	      await debitWallet(tx, user.id, debitCents);
431	      await tx.walletTransaction.create({
432	        data: {
433	          userId: user.id,
434	          amountCents: -debitCents,
435	          description: `Business Email: ${plan.name} for ${name} — ${termLabel}${note}`,
436	        },
437	      });
438	      const sub = await tx.emailSubscription.create({
439	        // Cast: the symlinked prod Prisma client's types predate `termMonths` /
440	        // `annualDiscountPct` on EmailSubscription until regenerated at deploy.
441	        data: {
442	          userId: user.id,
443	          domainName: name,
444	          emailPlanId: plan.id,
445	          status: "ACTIVE",
446	          autoRenew: true,
447	          // The term the customer chose, and the annual rate frozen at sale, so the
448	          // renewal sweep bills the SAME price it was ordered at.
449	          termMonths: term,
450	          annualDiscountPct: annualPct,
451	          expiresAt: addMonths(new Date(), term),
452	          // In-account domains: we control DNS, so treat as verified now. External
453	          // domains: not verified until the customer publishes DNS + we confirm it.
454	          external,
455	          verified: !external,
456	          verifiedAt: external ? null : new Date(),
457	          verifyToken: external ? randomBytes(24).toString("hex") : null,
458	        } as Prisma.EmailSubscriptionUncheckedCreateInput,
459	      });
460	      if (promoClaimId) await setPromoOrderRef(tx, promoClaimId, sub.id, debitCents);
461	    });
462	  } catch (e) {
463	    if (e instanceof InsufficientBalanceError) {
464	      return { error: "Insufficient balance. Top up your wallet first." };
465	    }
466	    throw e;
467	  }
468	
469	  await db.auditLog.create({
470	    data: {
471	      userId: user.id,
472	      action: "emailhosting.order",
473	      detail: `${name} plan=${plan.name}${external ? " (external — DNS verification required)" : ""}`,
474	    },
475	  });
476	  revalidatePath("/dashboard/email");
477	  return { ok: true };
478	}
479	
480	/**
481	 * Fulfil a CARD-funded business-email order from its PAID Stripe session. Safe to
482	 * expose as a server action: it trusts NOTHING from its caller but a Stripe session
483	 * id, which it re-retrieves and re-classifies server-side — a forged or foreign id
484	 * classifies as anything-but-emailOrder and returns a no-op. Called ONLY by
485	 * lib/fulfil-checkout.ts (the shared webhook+redirect bus) AFTER it has credited the
486	 * card leg to the wallet; this then runs the SAME `orderEmailHostingCore` the wallet
487	 * path uses (whose domain dupe guard is the placement idempotency), so the wallet is
488	 * debited once and a webhook + redirect can never create two subscriptions.
489	 */
490	export async function placeEmailCardOrder(sessionId: string): Promise<Result | { skip: true }> {
491	  const purpose = await getCheckoutPurpose(sessionId);
492	  if (purpose.kind !== "emailOrder") return { skip: true };
493	  const user = await db.user.findUnique({ where: { id: purpose.userId } });
494	  if (!user) return { error: "user not found for paid email order" };
495	  const { domainName, emailPlanId, termMonths } = purpose.intent;
496	  return orderEmailHostingCore(user, domainName, emailPlanId, termMonths);
497	}
498	
499	// ---------- External-domain DNS setup + verification ----------
500	
501	/**
502	 * Return the DNS records a customer must publish at their registrar for an
503	 * EXTERNAL domain so mail flows through the Nxeon mail server, plus the
504	 * ownership-verification record. Ownership-checked (caller must own the sub).
505	 *
506	 * The DKIM record is fetched from Mailcow (`mcGetDkim`) and cached in
507	 * `dkimRecord`; when Mailcow isn't configured (or has no key yet) a placeholder
508	 * note is returned so the panel still renders.
509	 */
510	export async function getEmailDnsRecords(
511	  subscriptionId: string,
512	): Promise<{
513	  error?: string;
514	  records?: DnsRecord[];
515	  verified?: boolean;
516	  external?: boolean;
