595	/**
596	 * Verify that an EXTERNAL domain's owner has published our verification record.
597	 * Resolves the `_nxeon-verify` TXT via DNS and confirms it contains
598	 * `nxeon-verify=<verifyToken>`; the MX pointing at the mail host is accepted as
599	 * corroboration. The result is derived entirely server-side from live DNS —
600	 * client input never decides the outcome. Rate-limited per user + subscription.
601	 */
602	export async function verifyEmailDomain(subscriptionId: string): Promise<Result> {
603	  const user = await requireUser();
604	
605	  const sub = await db.emailSubscription.findUnique({ where: { id: subscriptionId } });
606	  if (!sub) return { error: "Subscription not found." };
607	  if (sub.userId !== user.id) return { error: "Not your subscription." };
608	  if (!sub.external) return { error: "This domain is managed by Nxeon — no verification needed." };
609	  if (sub.verified) return { ok: true };
610	  if (!sub.verifyToken) return { error: "No verification token on this subscription." };
611	
612	  const rl = checkRateLimit(`email-verify:${user.id}:${sub.id}`, {
613	    max: 6,
614	    windowMs: 60_000,
615	  });
616	  if (!rl.ok) {
617	    return { error: `Too many verification attempts. Try again in ${rl.retryAfterSec}s.` };
618	  }
619	
620	  const domain = sub.domainName;
621	  const expected = `nxeon-verify=${sub.verifyToken}`;
622	
623	  // Primary signal: the verification TXT record must contain our exact token.
624	  let tokenFound = false;
625	  try {
626	    const txt = await resolveTxt(`_nxeon-verify.${domain}`);
627	    // Each record may be split into multiple strings — join per-record chunks.
628	    tokenFound = txt.some((chunks) => chunks.join("").trim() === expected);
629	  } catch {
630	    tokenFound = false;
631	  }
632	
633	  // Corroboration: MX pointing at the mail host (does not substitute for the token).
634	  let mxOk = false;
635	  try {
636	    const mx = await resolveMx(domain);
637	    mxOk = mx.some((r) => r.exchange.replace(/\.$/, "").toLowerCase() === MAIL_HOST);
638	  } catch {
639	    mxOk = false;
640	  }
641	
642	  if (!tokenFound) {
643	    return {
644	      error: mxOk
645	        ? "MX is set, but the _nxeon-verify TXT record isn't visible yet. DNS can take a few minutes to propagate."
646	        : "Verification record not found yet. Add the _nxeon-verify TXT record and try again (DNS can take a few minutes).",
647	    };
648	  }
649	
650	  await db.emailSubscription.update({
651	    where: { id: sub.id },
652	    data: { verified: true, verifiedAt: new Date() },
653	  });
654	
655	  await db.auditLog.create({
656	    data: {
657	      userId: user.id,
658	      action: "emailhosting.verify",
659	      detail: `${domain}${mxOk ? " (MX + TXT)" : " (TXT)"}`,
660	    },
661	  });
662	  revalidatePath("/dashboard/email");
663	  return { ok: true };
664	}
