668	/**
669	 * Run the SPF / DKIM / DMARC / MX self-check for a subscription the caller owns.
670	 *
671	 * WHY: "my mail goes to spam" was previously undiagnosable from inside the
672	 * product — the platform owner hit exactly this and had to reach for an external
673	 * tool. This returns pass/fail per record with the value actually observed beside
674	 * the expected one, so the customer can see which DNS row is wrong.
675	 *
676	 * Two correctness rules this depends on:
677	 *   - DNS is read from the ZONE'S AUTHORITATIVE NAMESERVERS, never the system
678	 *     resolver (see lib/mail/deliverability.ts — this host's `hosts: files …`
679	 *     nsswitch order can answer from /etc/hosts and looks like a real lookup).
680	 *   - DKIM is compared against Mailcow's LIVE key, not `sub.dkimRecord`, which is
681	 *     a write-once cache that can outlive a key rotation.
682	 *
683	 * Rate-limited: each run makes several outbound DNS queries plus one Mailcow call.
684	 */
685	export async function checkEmailDeliverability(
686	  subscriptionId: string,
687	): Promise<{ error?: string; report?: DeliverabilityReport }> {
688	  const user = await requireUser();
689	
690	  const sub = await db.emailSubscription.findUnique({ where: { id: subscriptionId } });
691	  if (!sub) return { error: "Subscription not found." };
692	  if (sub.userId !== user.id) return { error: "Not your subscription." };
693	  // A cancelled subscription's domain may since have been taken by another
694	  // customer (the duplicate guard in orderEmailHosting only excludes CANCELLED
695	  // rows), so the old owner must not keep a live probe pointed at it.
696	  if (sub.status === "CANCELLED") return { error: "This subscription is cancelled." };
697	
698	  // NOTE on domain verification: this check deliberately does NOT require
699	  // `sub.verified`, unlike every action that changes mail routing. It only READS
700	  // public DNS and Mailcow's public DKIM key, changes nothing, and an unverified
701	  // domain is precisely the case a customer needs it for — gating it would hide
702	  // the diagnosis exactly when the records are wrong. Ownership of the
703	  // subscription is still required so the panel can't be used to scan arbitrary
704	  // domains through our server.
705	  const rl = checkRateLimit(`email-deliverability:${user.id}`, { max: 10, windowMs: 60_000 });
706	  if (!rl.ok) return { error: `Too many checks. Try again in ${rl.retryAfterSec}s.` };
707	
708	  // LIVE key only. A failure here degrades the DKIM row to "unknown" rather than
709	  // silently comparing against a cached value that may no longer sign anything.
710	  let dkim: { selector: string; txt: string } | null = null;
711	  if (mailcowConfigured()) {
712	    try {
713	      const live = await mcGetDkimDetails(sub.domainName);
714	      if (live) dkim = { selector: live.selector, txt: live.txt };
715	    } catch (e) {
716	      console.warn(`[mailcow] live dkim lookup for ${sub.domainName} failed:`, e);
717	    }
718	  }
719	
720	  try {
721	    const report = await checkDeliverability({
722	      domain: sub.domainName,
723	      mailHost: MAIL_HOST,
724	      spfInclude: SPF_INCLUDE,
725	      spfExpected: SPF_VALUE,
726	      dmarcExpected: DMARC_VALUE,
727	      dkim,
728	    });
729	    return { report };
730	  } catch (e) {
731	    console.warn(`[deliverability] check for ${sub.domainName} failed:`, e);
732	    return { error: "Couldn't complete the DNS check right now. Please try again in a moment." };
733	  }
734	}
