739	/**
740	 * Add a mailbox to a subscription the caller owns. Enforces the plan's mailbox
741	 * quota and address uniqueness within the subscription, records the intended
742	 * mailbox (status PROVISIONING), then attempts to provision it on Mailcow. A
743	 * Mailcow failure leaves the row as FAILED (retryable) but never fails the call.
744	 */
745	export async function addMailbox(subscriptionId: string, localPart: string): Promise<Result> {
746	  const user = await requireUser();
747	
748	  const sub = await db.emailSubscription.findUnique({
749	    where: { id: subscriptionId },
750	    include: { emailPlan: true, mailboxes: true },
751	  });
752	  if (!sub) return { error: "Subscription not found." };
753	  if (sub.userId !== user.id) return { error: "Not your subscription." };
754	  if (sub.status === "CANCELLED") return { error: "This subscription is cancelled." };
755	  // SECURITY (added 2026-07-25): defence in depth against the cross-tenant
756	  // takeover fixed in subscribeEmail(). Owning the subscription ROW is not proof
757	  // of owning the DOMAIN — and because Mailcow keys mailboxes by address, any
758	  // mailbox minted here acts on that domain's real mail. An external domain must
759	  // prove control via DNS before it can mint a single address, so even if a
760	  // duplicate subscription is ever created again this cannot be weaponised.
761	  if (sub.external && !sub.verified) {
762	    return {
763	      error: "Verify this domain first — add the DNS record shown on this page, then click Verify.",
764	    };
765	  }
766	
767	  const local = String(localPart ?? "").trim().toLowerCase();
768	  if (!localPartRe.test(local) || local.length > 64) {
769	    return { error: "Enter a valid mailbox name (letters, numbers, . _ - )." };
770	  }
771	
772	  const address = `${local}@${sub.domainName}`;
773	
774	  if (sub.mailboxes.length >= sub.emailPlan.mailboxes) {
775	    return {
776	      error: `Plan limit reached (${sub.emailPlan.mailboxes} mailbox${sub.emailPlan.mailboxes === 1 ? "" : "es"}). Upgrade to add more.`,
777	    };
778	  }
779	  if (sub.mailboxes.some((m) => m.address.toLowerCase() === address)) {
780	    return { error: "That address already exists." };
781	  }
782	
783	  // Per-mailbox quota (MB) comes from the plan tier's per-mailbox storage (GB).
784	  const quotaMB = sub.emailPlan.storageGB * 1024;
785	
786	  const mailbox = await db.mailbox.create({
787	    data: { subscriptionId: sub.id, address, quotaMB, status: "PROVISIONING" },
788	  });
789	
790	  await db.auditLog.create({
791	    data: { userId: user.id, action: "mailbox.add", detail: address },
792	  });
793	
794	  // Additive, failure-tolerant provisioning — never throws out of the flow.
795	  await provisionMailboxOnMailcow({
796	    id: mailbox.id,
797	    address: mailbox.address,
798	    quotaMB,
799	    subscription: { domainName: sub.domainName },
800	  });
801	
802	  revalidatePath("/dashboard/email");
803	  return { ok: true };
804	}
