853	/** Remove a mailbox the caller owns (via its subscription). */
854	export async function removeMailbox(mailboxId: string): Promise<Result> {
855	  const user = await requireUser();
856	
857	  const mailbox = await db.mailbox.findUnique({
858	    where: { id: mailboxId },
859	    include: { subscription: true },
860	  });
861	  if (!mailbox) return { error: "Mailbox not found." };
862	  if (mailbox.subscription.userId !== user.id) return { error: "Not your mailbox." };
863	
864	  // Delete on Mailcow BEFORE dropping our row — and distinguish the two failure
865	  // modes, because they demand opposite actions:
866	  //
867	  //   - Mailcow REFUSED (reachable, returned an error): the mail server and our
868	  //     database disagree about this mailbox. Deleting our row here would leave a
869	  //     LIVE mailbox still receiving the customer's mail with no record of it in
870	  //     the product — silent data loss. Surface the error and keep the row.
871	  //   - Mailcow UNREACHABLE (transport failure): the server may just be down.
872	  //     Blocking removal forever on an outage is wrong, so we drop our row and
873	  //     tell the customer the mailbox itself may still exist and to retry once
874	  //     mail service is back.
875	  //
876	  // The previous `.catch(() => {})` collapsed both into "deleted, ok:true" — the
877	  // worse answer in every case.
878	  let mailcowUnreachable = false;
879	  if (mailcowConfigured()) {
880	    try {
881	      await mcDeleteMailbox(mailbox.address);
882	    } catch (e) {
883	      if (isMailcowUnreachable(e)) {
884	        mailcowUnreachable = true;
885	        console.warn(`[mailcow] delete ${mailbox.address}: unreachable, removing local record anyway:`, e);
886	      } else {
887	        console.error(`[mailcow] delete ${mailbox.address} REFUSED:`, e);
888	        return {
889	          error:
890	            "The mail server wouldn't remove this mailbox, so we've left it in place rather than lose your mail. Please try again in a moment, or contact support if it keeps happening.",
891	        };
892	      }
893	    }
894	  }
895	
896	  await db.mailbox.delete({ where: { id: mailbox.id } });
897	
898	  await db.auditLog.create({
899	    data: {
900	      userId: user.id,
901	      action: "mailbox.remove",
902	      detail: mailcowUnreachable ? `${mailbox.address} (mailcow unreachable — server-side delete not confirmed)` : mailbox.address,
903	    },
904	  });
905	  revalidatePath("/dashboard/email");
906	  return mailcowUnreachable
907	    ? {
908	        ok: true,
909	        warning:
910	          "Removed from your account. The mail server was unreachable, so the mailbox itself may still exist — it will be cleared when mail service is back, or contact support if messages keep arriving.",
911	      }
912	    : { ok: true };
913	}
