1066	export async function saveCloudflareToken(token: string): Promise<Result> {
1067	  const user = await requireUser();
1068	
1069	  const t = String(token ?? "").trim();
1070	  if (!t) return { error: "Paste your Cloudflare API token." };
1071	  if (t.length < 20 || t.length > 200) {
1072	    return { error: "That doesn't look like a Cloudflare API token." };
1073	  }
1074	
1075	  const rl = checkRateLimit(`cf-token:${user.id}`, { max: 6, windowMs: 60_000 });
1076	  if (!rl.ok) return { error: `Too many attempts. Try again in ${rl.retryAfterSec}s.` };
1077	
1078	  let valid = false;
1079	  try {
1080	    valid = await cfVerifyToken(t);
1081	  } catch (e) {
1082	    console.warn("[cloudflare] token verify failed:", e);
1083	    return { error: "Couldn't reach Cloudflare to verify the token. Try again shortly." };
1084	  }
1085	  if (!valid) {
1086	    return {
1087	      error: "Cloudflare rejected that token. Check it's active and scoped to Zone → DNS → Edit.",
1088	    };
1089	  }
1090	
1091	  await db.user.update({
1092	    where: { id: user.id },
1093	    data: { cloudflareTokenEnc: encryptSecret(t) },
1094	  });
