export async function adminTerminateHostingAccount(id: string): Promise<{ error?: string; ok?: boolean }> {
  await requireArea("fleet");
  const a = await db.hostingAccount.findUnique({ where: { id }, select: { status: true } });
  if (!a) return { error: "Account not found." };
  if (a.status === "DELETING") return { error: "Already terminating." };
  await db.hostingAccount.update({ where: { id }, data: { status: "DELETING" } });
  await queueLifecycleTask(id, "TERMINATE");
  revalidatePath("/admin/hosting");
  return { ok: true };
}

/**
 * Self-serve cancel: the OWNER closes their own hosting account. Mirrors
 * `adminTerminateHostingAccount` (set DELETING → queue a TERMINATE lifecycle task
 * for the provisioner, which removes files, databases and sites) but gated to the
 * account owner instead of the fleet admin area. Ownership is checked the SAME way
 * every other customer hosting action in this file does (`a.userId !== user.id`,
 * with ADMIN allowed through). Irreversible; the UI requires a strong typed
 * confirmation before calling this. Refuses cleanly if the caller doesn't own the
 * account or it is already terminating.
 */
export async function cancelHostingAccount(accountId: string): Promise<{ error?: string; ok?: boolean }> {
  const user = await requireUser();
  // Spend/destroy path: an impersonating admin must not close a customer's account
  // while acting as them (same discipline as the order paths above).
  await assertNotImpersonating();
  const a = await db.hostingAccount.findUnique({ where: { id: accountId }, select: { userId: true, status: true } });
  if (!a) return { error: "Account not found." };
  if (a.userId !== user.id && user.role !== "ADMIN") return { error: "Forbidden." };
  if (a.status === "DELETING") return { error: "This account is already being cancelled." };
  await db.hostingAccount.update({ where: { id: accountId }, data: { status: "DELETING" } });
  await queueLifecycleTask(accountId, "TERMINATE");
  await db.auditLog.create({
    data: { userId: user.id, action: "hosting.cancel", detail: `self-serve cancel · ${accountId}` },
  }).catch(() => {});
  revalidatePath("/dashboard/hosting");
  revalidatePath(`/dashboard/hosting/${accountId}`);
  return { ok: true };
}

